create  view [dbo].[sanadpar_sub] as SELECT PGET_HED.MOLAH, PAY_GETP.DATE_S, PAY_GETP.SHOBEH, PAY_GETP.MABL AS mabld, PAY_GETP.N_HESAB, PGET_LST.*, CUST_HESAB.hes, CUST_HESAB.NAME, TCOD_BANKS.NAMES, PGET_HED.IDK FROM PGET_HED INNER JOIN PGET_LST ON PGET_HED.ID = PGET_LST.ID AND PGET_HED.DATE = PGET_LST.DATE INNER JOIN PAY_GETP ON PGET_LST.N_SERI = PAY_GETP.N_SERI AND PGET_LST.BANK = PAY_GETP.BANK INNER JOIN CUST_HESAB ON PGET_LST.FHES = CUST_HESAB.hes LEFT OUTER JOIN TCOD_BANKS ON PAY_GETP.BANK = TCOD_BANKS.CODE WHERE (PGET_LST.NO_AM = 2) AND (PAY_GETP.N_KOL <> 911) UNION SELECT PGET_HED.MOLAH, PAY_GETD.DATE_S, PAY_GETD.SHOBEH, PAY_GETD.MABL AS mabld, PAY_GETD.N_HESAB, PGET_LST.*, CUST_HESAB.hes, CUST_HESAB.NAME, TCOD_BANKS.NAMES, PGET_HED.IDK FROM TCOD_BANKS INNER JOIN PAY_GETD ON TCOD_BANKS.CODE = PAY_GETD.BANK RIGHT OUTER JOIN PGET_HED INNER JOIN PGET_LST ON PGET_HED.ID = PGET_LST.ID AND PGET_HED.DATE = PGET_LST.DATE INNER  JOIN CUST_HESAB ON PGET_LST.FHES = CUST_HESAB.hes ON PAY_GETD.BANK = PGET_LST.BANK AND PAY_GETD.N_SERI = PGET_LST.N_SERI WHERE (PGET_LST.NO_AM = 2) AND (PGET_LST.NAHVA > 3) AND (PAY_GETD.N_KOL <> 911 OR PAY_GETD.N_KOL IS NULL)
